import {fields,defaultRules} from './rules.mjs';
export const norm=s=>String(s??'').toLowerCase().replace(/[^a-z0-9]/g,'');
export const colName=n=>{let s='';for(;n>0;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s;};
export const address=a=>{const m=String(a).replaceAll('$','').match(/^([A-Z]+)(\d+)$/i);if(!m)return null;return {col:[...m[1].toUpperCase()].reduce((v,c)=>v*26+c.charCodeAt(0)-64,0),row:+m[2]};};
const isNum=v=>typeof v==='number'&&Number.isFinite(v);
const blank=v=>v===null||v===undefined||v==='';
const close=(a,b)=>Math.abs(a-b)<=Math.max(0.000001,Math.abs(b)*0.00001);
export function sheetRole(name,cells={}){let n=name.toLowerCase();for(const [r,p]of Object.entries({input:/data add|kaizen index|savings sheet/,dashboard:/dashboard/,benchmark:/benchmark/,evidence:/evidence/,graph:/graph/,configuration:/formulae|company information/,management:/responsibility|activities/}))if(p.test(n))return r;return Object.values(cells).some(c=>c.f)?'calculation':'helper';}
export function classify(w){return w.sheets.some(s=>/^productivity\s*\(/i.test(s.name))?'Master':w.sheets.some(s=>norm(s.name)==='dataaddsheet')?'MCLS':'Unmapped';}
export function companyName(name){return name.replace(/\s*G12.*$/i,'').replace(/\.(xlsx|json)$/i,'').trim();}
const refRE=/(?:'((?:[^']|'')+)'!|([A-Za-z_][\w. ]*)!)?(\$?[A-Z]{1,3}\$?\d+)(?::(\$?[A-Z]{1,3}\$?\d+))?/g;
export function references(f,sheet){const cleaned=String(f).replace(/"(?:[^"]|"")*"/g,'""');return [...cleaned.matchAll(refRE)].filter(m=>!/[A-Za-z0-9_]/.test(cleaned[m.index-1]||'')).map(m=>({sheet:(m[1]?.replaceAll("''","'")||m[2]||sheet),cell:m[3].replaceAll('$',''),end:m[4]?.replaceAll('$','')}));}
export function normalizeFormula(f,origin){const o=address(origin);return String(f).replace(/"(?:[^"]|"")*"|(?:'((?:[^']|'')+)'!|([A-Za-z_][\w. ]*)!)?(\$?)([A-Z]{1,3})(\$?)(\d+)/g,(all,s1,s2,ac,c,ar,r)=>{if(all[0]==='"')return all;const a=address(c+r);return `${s1||s2?`'${s1||s2}'!`:''}R${ar?r:`[${+r-o.row}]`}C${ac?a.col:`[${a.col-o.col}]`}`;}).toUpperCase().replace(/\s+/g,'');}

